// Refresh each open market's resolution rules text.
//
// WHY THIS MATTERS: the rules text is what says WHICH station and WHICH
// surface settles the market. If Polymarket changes it mid-life, every
// probability AD4 computed against the old station is measuring the wrong
// thing. This workflow exists to catch that, not for bookkeeping.
//
// SCHEMA NOTE: `markets.rules_text` / `rules_fetched_at` / `rules_changed_at`
// are guaranteed by sql/ad4_00_preflight.sql. If your real P0.5 writes the
// rules somewhere else, run sql/ad4_99_verify.sql section 7 to see the true
// shape and point this at it instead.
const existing = $('Load open markets').all().map(i => i.json);
const fetched = $('Fetch rules').all().map(i => i.json).flat();
const now = new Date().toISOString();

const prior = new Map(existing.map(m => [String(m.market_id), m]));
const rows = [], changed = [];

for (const f of fetched) {
  const id = String(f.market_id || f.id || '');
  const before = prior.get(id);
  if (!before) continue;

  const text = (f.rules || f.description || f.rules_text || '').trim();
  if (!text) continue;

  const didChange = (before.rules_text || '').trim() !== text;
  if (didChange && before.rules_text) changed.push({ market_id: id, city_key: before.city_key });

  rows.push({
    market_id: id,
    rules_text: text,
    rules_fetched_at: now,
    // Only stamp rules_changed_at when the text actually moved, so the
    // column means "when did the terms last change", not "when did we poll".
    rules_changed_at: didChange ? now : (before.rules_changed_at || null),
  });
}

return [{ json: { rows, n: rows.length, changed, n_changed: changed.length } }];

const p = $('Diff rules').first().json;
if (p.n_changed > 0) {
  const list = p.changed.map(c => `${c.city_key || c.market_id}`).join(', ');
  return [{ json: { summary:
    `AD4 P0.5: ${p.n} markets refreshed. RULES CHANGED on ${p.n_changed}: ${list}. ` +
    `Re-read those before trusting any probability computed against them.` } }];
}
return [{ json: { summary: `AD4 P0.5: ${p.n} markets refreshed, no rule changes.` } }];
